",code:"// Define a tool with its interface\ninterface WeatherTool {\n  name: string;\n  description: string;\n  function: (args: any) => Promise<any>;\n  parameters: {\n    type: string;\n    properties: Record<string, any>;\n    required: string[];\n  };\n}\n\n// Implement the tool\nconst weatherTool: WeatherTool = {\n  name: 'get_weather',\n  description: 'Get current weather for a location',\n  parameters: {\n    type: 'object',\n    properties: {\n      location: {\n        type: 'string',\n        description: 'City name or coordinates'\n      },\n      units: {\n        type: 'string',\n        enum: ['celsius', 'fahrenheit']\n      }\n    },\n    required: ['location']\n  },\n  function: async (args) => {\n    const { location, units = 'celsius' } = args;\n    // Implementation of weather fetching logic\n    return { temperature: 25, units, location };\n  }\n};",title:"Tool Implementation",showLineNumbers:!0}),(0,Te.jsx)(Ue,{type:"tip",title:"Tool Design Tips",children:(0,Te.jsxs)("ul",{children:[(0,Te.jsx)("li",{children:"Keep tools focused and single-purpose"}),(0,Te.jsx)("li",{children:"Include clear error handling"}),(0,Te.jsx)("li",{children:"Document input/output formats"}),(0,Te.jsx)("li",{children:"Consider rate limiting"})]})})]}),(0,Te.jsxs)(Ge,{id:"implementation",title:"Implementation Guide",children:[(0,Te.jsx)("p",{children:"Here's a complete implementation of an agent with function calling capabilities:"}),(0,Te.jsx)(Ke,{language:"typescript",code:"import { OpenAI } from 'openai';\nimport { Tool } from './types';\n\nclass WeatherAgent {\n  private tools: Tool[];\n  private llm: OpenAI;\n\n  constructor() {\n    this.llm = new OpenAI();\n    this.tools = [\n      {\n        name: 'get_weather',\n        function: this.getWeather.bind(this),\n        description: 'Get current weather for a location'\n      }\n    ];\n  }\n\n  async processQuery(query: string) {\n    const response = await this.llm.chat.completions.create({\n      model: 'gpt-3.5-turbo',\n      messages: [{ role: 'user', content: query }],\n      functions: this.tools.map(tool => ({\n        name: tool.name,\n        description: tool.description,\n        parameters: tool.parameters\n      }))\n    });\n\n    if (response.choices[0].function_call) {\n      const functionCall = response.choices[0].function_call;\n      const tool = this.tools.find(t => t.name === functionCall.name);\n      \n      if (tool) {\n        const result = await tool.function(\n          JSON.parse(functionCall.arguments)\n        );\n        return result;\n      }\n    }\n\n    return response.choices[0].message.content;\n  }\n}",title:"Agent Implementation",showLineNumbers:!0}),(0,Te.jsx)(Ue,{type:"warning",title:"Implementation Considerations",children:(0,Te.jsxs)("ul",{children:[(0,Te.jsx)("li",{children:"Proper error handling"}),(0,Te.jsx)("li",{children:"Input validation"}),(0,Te.jsx)("li",{children:"Response formatting"}),(0,Te.jsx)("li",{children:"Tool registration system"})]})})]}),(0,Te.jsxs)(Ge,{id:"best-practices",title:"Best Practices",children:[(0,Te.jsx)("h3",{children:"Tool Design Principles"}),(0,Te.jsxs)("ul",{children:[(0,Te.jsx)("li",{children:"Keep tools atomic and focused"}),(0,Te.jsx)("li",{children:"Implement proper error handling"}),(0,Te.jsx)("li",{children:"Document tool capabilities clearly"}),(0,Te.jsx)("li",{children:"Include validation and safety checks"})]}),(0,Te.jsx)("h3",{children:"Error Handling"}),(0,Te.jsxs)("ul",{children:[(0,Te.jsx)("li",{children:"Validate inputs before execution"}),(0,Te.jsx)("li",{children:"Provide meaningful error messages"}),(0,Te.jsx)("li",{children:"Implement fallback mechanisms"}),(0,Te.jsx)("li",{children:"Log errors for debugging"})]}),(0,Te.jsx)(Ue,{type:"note",title:"Security Considerations",children:(0,Te.jsxs)("ul",{children:[(0,Te.jsx)("li",{children:"Implement access controls"}),(0,Te.jsx)("li",{children:"Validate user inputs"}),(0,Te.jsx)("li",{children:"Rate limit tool usage"}),(0,Te.jsx)(